import { html, LitElement, TemplateResult } from 'lit';
import { customElement, property, query } from 'lit/decorators.js';
import { OpcoesImpressao } from '../../model/opcoes-impressao.model';
import '@awesome.me/webawesome/dist/components/input/input.js';
import '@awesome.me/webawesome/dist/components/select/select.js';
import '@awesome.me/webawesome/dist/components/option/option.js';

@customElement('lexml-ui-opcoes-impressao')
export class OpcoesImpressaoComponent extends LitElement {
  @query('#select-tamanho-fonte')
  tamanhoFonte!: HTMLElement & { value: string };

  private _opcoesImpressao: OpcoesImpressao = new OpcoesImpressao();
  @property({ type: Object, state: true })
  set opcoesImpressao(value: OpcoesImpressao) {
    this._opcoesImpressao = value ? value : new OpcoesImpressao();
    this.requestUpdate();
  }

  get opcoesImpressao(): OpcoesImpressao {
    return this._opcoesImpressao;
  }

  public getOpcoesImpressao(): OpcoesImpressao {
    const tamanho = Number(
      this.tamanhoFonte?.value ?? this._opcoesImpressao?.tamanhoFonte ?? 14,
    );

    return {
      imprimirBrasao: !!this._opcoesImpressao?.imprimirBrasao,
      textoCabecalho: this._opcoesImpressao?.textoCabecalho ?? '',
      reduzirEspacoEntreLinhas:
        !!this._opcoesImpressao?.reduzirEspacoEntreLinhas,
      tamanhoFonte: Number.isFinite(tamanho) ? tamanho : 14,
    };
  }

  private timerEmitirEventoOnChange = 0;

  protected firstUpdated(): void {
    this.tamanhoFonte.addEventListener(
      'wa-change',
      this._atualizarTamanhoFonte,
    );
  }
  render(): TemplateResult {
    return html`
      <style>
        fieldset {
          font-size: 14px;
          font-family: 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
          display: flex;
          flex-direction: column;
          gap: 0.5em;
          background-color: var(--wa-color-gray-95);
          box-shadow: var(--wa-shadow-m);
          flex-wrap: wrap;
          padding: 20px 20px;
          border: solid var(--wa-panel-border-width) var(--wa-color-gray-90);
          border-radius: var(--wa-border-radius-s);
          max-width: 655px;
          margin: 1em 0 2em 0;
        }

        legend {
          background-color: var(--wa-color-gray-90);
          font-weight: bold;
          border-radius: 5px;
          border: 1px solid var(--wa-color-gray-85);
          padding: 2px 5px;
          box-shadow: var(--wa-shadow-s);
          color: #333;
        }

        @media (max-width: 480px) {
        }
        wa-select {
          max-width: 400px;
        }
        label {
          line-height: var(--wa-toggle-size);
          font-size: var(--wa-font-size-xs);
          display: flex;
          align-items: center;
          gap: 5px;
        }
      </style>

      <fieldset class="lexml-opcoes-impressao">
        <legend>Opções de impressão</legend>
        <div>
          <label class="lbl-imprimir-brasao" for="chk-imprimir-brasao">
            <input
              type="checkbox"
              id="chk-imprimir-brasao"
              ?checked=${this._opcoesImpressao?.imprimirBrasao}
              @input=${(ev: Event): void => this._atualizarImprimirBrasao(ev)}
            />
            Imprimir brasão
          </label>
        </div>
        <wa-input
          type="text"
          id="input-cabecalho"
          name="textoCabecalho"
          label="Texto do cabeçalho"
          value=${this._opcoesImpressao?.textoCabecalho}
          @input=${(ev: Event): void => this._atualizarTextoCabecalho(ev)}
          size="small"
        ></wa-input>
        <div>
          <wa-select
            id="select-tamanho-fonte"
            label="Tamanho da letra"
            size="small"
            value=${this._opcoesImpressao?.tamanhoFonte}
          >
            <wa-option value="14">14</wa-option>
            <wa-option value="16">16</wa-option>
            <wa-option value="18">18</wa-option>
          </wa-select>
        </div>
        <div>
          <label class="lbl-reduzir-espaco" for="chk-reduzir-espaco">
            <input
              type="checkbox"
              id="chk-reduzir-espaco"
              ?checked=${this._opcoesImpressao?.reduzirEspacoEntreLinhas}
              @input=${(ev: Event): void =>
                this._atualizarReduzirEspacoEntreLinhas(ev)}
            />
            Reduzir espaço entre linhas
          </label>
        </div>
      </fieldset>
    `;
  }

  private _atualizarTextoCabecalho(ev: Event): void {
    this._opcoesImpressao.textoCabecalho = (
      ev.target as HTMLInputElement
    ).value;
    this.requestUpdate();
  }

  private _atualizarImprimirBrasao(ev: Event): void {
    this._opcoesImpressao.imprimirBrasao = (
      ev.target as HTMLInputElement
    ).checked;
    this.requestUpdate();
  }

  private _atualizarTamanhoFonte(ev: Event): void {
    const valorFonte = parseInt(
      (ev.currentTarget as HTMLElement & { value: string }).value,
    );
    this._opcoesImpressao.tamanhoFonte = valorFonte;
    this.requestUpdate();
  }

  private _atualizarReduzirEspacoEntreLinhas(ev: Event): void {
    this._opcoesImpressao.reduzirEspacoEntreLinhas = (
      ev.target as HTMLInputElement
    ).checked;
    this.requestUpdate();
  }

  private agendarEmissaoEventoOnChange(origemEvento: string): void {
    clearInterval(this.timerEmitirEventoOnChange);
    this.timerEmitirEventoOnChange = window.setTimeout(
      () => this.emitirEventoOnChange(origemEvento),
      50,
    );
  }

  private emitirEventoOnChange(origemEvento: string): void {
    this.dispatchEvent(
      new CustomEvent('onchange', {
        bubbles: true,
        composed: true,
        detail: {
          origemEvento,
        },
      }),
    );
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'lexml-ui-opcoes-impressao': OpcoesImpressaoComponent;
  }
}
